<script setup lang="ts">
import {computed,onMounted,ref,watch} from 'vue';
import {api,APIError} from '../api';
import type {Validation} from '../types';
import {emptySystem,parseSystemImport,normalizeSystemResponse,claimKinds,type SystemDesign,type SystemEvent,type SystemVerdict,type SystemCatalogEntry,type SystemResolution} from '../systemTypes';
import {useWorkspaceDraft} from '../composables/useWorkspaceDraft';
import {useActionFeedback} from '../composables/useNotifications';
import StudioRibbon from './StudioRibbon.vue';
import DraftStatus from './DraftStatus.vue';
import CanvasInspector from './CanvasInspector.vue';
import SystemCatalogPanel from './SystemCatalogPanel.vue';
interface Trace {events:SystemEvent[];verdicts:SystemVerdict[]}
interface Report {experiment:string;designId:string;designRevision:string;contractId:string;contractRevision:string;passed:boolean;limitations:string[];scenarios:{id:string;name:string;expectedStatus:string;passed:boolean;model:Trace;implementation:Trace}[]}
interface Evidence {id:string;createdAt:string;design:SystemDesign;report:Report;resolution?:SystemResolution}
const props = defineProps<{conformanceRequest?: number}>();
const draft=ref<SystemDesign>(emptySystem());
const importInput=ref<HTMLInputElement|null>(null);
const recovery=useWorkspaceDraft('system',{draft});
const tab=ref('Architecture'), selected=ref(''), panel=ref(''), library=ref<SystemDesign[]>([]), evidence=ref<Evidence|null>(null), history=ref<Evidence[]>([]);
const catalog=ref<SystemCatalogEntry[]>([]),resolution=ref<SystemResolution|null>(null),libraryOpen=ref(true);
const busy=ref(''),notice=ref(''),error=ref(''),validation=ref<Validation|null>(null);
watch(()=>props.conformanceRequest, value=>{if(value){tab.value='Claims';panel.value='';}},{immediate:true});
useActionFeedback('system',busy,notice,error);
const selectedComponent=computed(()=>draft.value.components.find(c=>c.id===selected.value));
const selectedIndex=computed(()=>draft.value.components.findIndex(c=>c.id===selected.value));
const staleEvidence=computed(()=>evidence.value && JSON.stringify(evidence.value.design)!==JSON.stringify(draft.value));
watch(draft,()=>{validation.value=null;resolution.value=null;},{deep:true});
async function action(label:string,fn:()=>Promise<void>){if(busy.value)return;busy.value=label;error.value='';notice.value='';try{await recovery.ready;await fn();}catch(e){error.value=e instanceof Error?e.message:String(e);if(e instanceof APIError && e.issues.length)validation.value={valid:false,issues:e.issues};}finally{busy.value='';}}
async function refresh(){library.value=await api<SystemDesign[]>('/systems');}
async function refreshCatalog(){catalog.value=await api<SystemCatalogEntry[]>('/systems/catalog');}
async function resolveReferences(){await action('Resolving references',async()=>{const snapshot=JSON.stringify(draft.value);const result=await api<SystemResolution>('/systems/resolve','POST',JSON.parse(snapshot));if(snapshot!==JSON.stringify(draft.value)){notice.value='Design changed during resolution. Resolve the current draft again.';return;}resolution.value=result;validation.value={valid:result.valid,issues:result.issues};notice.value=result.valid?'All direct references resolved. Port compatibility and execution support are separate checks.':'';});}
function addInstalled(entry:SystemCatalogEntry){addComponent();selectedComponent.value!.name=entry.name;selectedComponent.value!.definition={...(entry.kind==='definition'?{kind:'definition' as const}:{}),id:entry.id,version:entry.version};notice.value='Exact component reference added';}
function attachArtifact(entry:SystemCatalogEntry){const owner=selectedComponent.value;if(!owner)return;if(owner.artifacts.some(a=>a.kind===entry.kind&&a.id===entry.id&&a.version===entry.version)){notice.value='This exact artifact is already attached';return;}owner.artifacts.push({kind:entry.kind,id:entry.id,version:entry.version});notice.value='Artifact reference attached';}
function chooseDefinition(event:Event){const select=event.target as HTMLSelectElement;const entry=catalog.value[Number(select.value)];if(entry?.ready&&(entry.kind==='component'||entry.kind==='definition')&&selectedComponent.value)selectedComponent.value.definition={...(entry.kind==='definition'?{kind:'definition' as const}:{}),id:entry.id,version:entry.version};select.value='';}
function reset(){draft.value=emptySystem();selected.value='';panel.value='';evidence.value=null;history.value=[];tab.value='Architecture';notice.value='Empty system created. Previous draft is available in recovery.';}
async function load(id:string){await action('Loading system',async()=>{draft.value=normalizeSystemResponse(await api<SystemDesign>('/systems/'+encodeURIComponent(id)));selected.value='';panel.value='';evidence.value=null;history.value=[];notice.value='System loaded';});}
async function example(){await action('Loading reception example',async()=>{draft.value=normalizeSystemResponse(await api<SystemDesign>('/systems/example'));selected.value='';panel.value='';evidence.value=null;history.value=[];notice.value='Reception example loaded';});}
async function validate(){await action('Validating system',async()=>{validation.value=await api<Validation>('/systems/validate','POST',draft.value);notice.value=validation.value.valid?'System structure and contract are valid':'';});}
async function save(){await action('Saving system',async()=>{const snapshot=JSON.stringify(draft.value);const saved=normalizeSystemResponse(await api<SystemDesign>('/systems/'+encodeURIComponent(draft.value.id),'PUT',JSON.parse(snapshot)));if(JSON.stringify(draft.value)===snapshot)draft.value=saved;await refresh();notice.value=JSON.stringify(draft.value)===JSON.stringify(saved)?'System saved to PostgreSQL':'Snapshot saved. Your newer local edits were kept.';});}
async function run(){await action('Running conformance experiment',async()=>{evidence.value=await api<Evidence>('/systems/conformance','POST',{design:draft.value});tab.value='Evidence';panel.value='';notice.value=evidence.value.report.passed?'All scenario expectations met, including negative controls':'Some scenario expectations were not met';});}
async function importDesign(event:Event){const input=event.target as HTMLInputElement;const file=input.files?.[0];input.value='';if(!file)return;await action('Importing system',async()=>{if(file.size>2_000_000)throw new Error('System file exceeds the 2 MB import limit.');const candidate=parseSystemImport(await file.text());const checked=await api<Validation>('/systems/validate','POST',candidate);if(!checked.valid)throw new Error('Import rejected: '+checked.issues.map(i=>i.path+': '+i.message).join('; ')+'. Current draft was kept.');draft.value=candidate;selected.value='';panel.value='';evidence.value=null;history.value=[];notice.value='System imported and validated';});}
async function loadHistory(){await action('Loading evidence history',async()=>{history.value=await api<Evidence[]>('/systems/evidence?systemId='+encodeURIComponent(draft.value.id));tab.value='Evidence';});}
function addComponent(){const id='component-'+crypto.randomUUID().slice(0,8);draft.value.components.push({id,name:'New component',definition:{id:'',version:'1.0.0'},artifacts:[],bindings:[]});selected.value=id;panel.value='component';tab.value='Architecture';}
function removeComponent(){const id=selected.value;draft.value.components=draft.value.components.filter(c=>c.id!==id);draft.value.connections=draft.value.connections.filter(c=>c.source!==id&&c.target!==id);for(const plan of draft.value.deploymentPlans)plan.placements=plan.placements.filter(p=>p.componentId!==id);panel.value='';selected.value='';}
function addConnection(){draft.value.connections.push({id:'connection-'+crypto.randomUUID().slice(0,8),source:draft.value.components[0]?.id||'',target:draft.value.components[1]?.id||'',kind:'request'});tab.value='Architecture';panel.value='connections';}
function addClaim(){draft.value.contract.claims.push({id:'claim-'+crypto.randomUUID().slice(0,8),kind:'exactly_one_record',description:''});tab.value='Claims';}
function addPlan(){draft.value.deploymentPlans.push({id:'plan-'+crypto.randomUUID().slice(0,8),name:'New deployment plan',resources:[],placements:[]});tab.value='Deployment';}
function invalid(path:string){return validation.value?.issues.some(i=>i.path===path||i.path.startsWith(path+'.')||i.path.startsWith(path+'['));}
function locate(path:string){const match=/components\[(\d+)\]/.exec(path);if(match){selected.value=draft.value.components[Number(match[1])]?.id||'';tab.value='Architecture';panel.value='component';}else if(path.startsWith('connections')){tab.value='Architecture';panel.value='connections';}else if(path.startsWith('contract'))tab.value='Claims';else if(path.startsWith('deploymentPlans'))tab.value='Deployment';else panel.value='system';}
function exportDesign(){const url=URL.createObjectURL(new Blob([JSON.stringify(draft.value,null,2)],{type:'application/json'}));const link=document.createElement('a');link.href=url;link.download='system-design.json';link.click();URL.revokeObjectURL(url);}
onMounted(()=>{void action('Loading systems and catalog',async()=>{await refresh();await refreshCatalog();});});
</script>
<template>
<section class="system-workbench" :aria-busy="!!busy">
 <StudioRibbon workspace="system" :title="draft.name" :active="tab" :structure="['Architecture','Deployment']" :behavior="['Claims']" :execution="['Evidence']" @select="tab=$event;panel=''">
  <template #status><DraftStatus :draft="recovery" /></template>
  <template #file><div class="commands"><button @click="reset" :disabled="!!busy">New empty system</button><button @click="save" :disabled="!!busy">Save system</button><button @click="example" :disabled="!!busy">Load reception example</button><button @click="exportDesign">Export JSON</button><button @click="importInput?.click()" :disabled="!!busy">Import JSON</button><input ref="importInput" type="file" accept="application/json,.json" hidden @change="importDesign" /><select aria-label="Load saved system" @change="load(($event.target as HTMLSelectElement).value)" :disabled="!!busy"><option value="">Open saved system…</option><option v-for="item in library" :key="item.id" :value="item.id">{{item.name}} · {{item.revision}}</option></select></div></template>
  <template #help><p>Assemble versioned component references, attach a contract, and compare the model with the fixed Go reception intake implementation. The experiment does not generate code from arbitrary designs. The restart case recreates the service object against durable storage; it does not kill an operating-system process. Deployment plans describe bindings; they do not provision infrastructure.</p><p>Claims describe bounded execution evidence. Missing evidence is inconclusive. Assumptions are declared preconditions, not automatically proven facts.</p></template>
  <div class="commands"><button @click="panel='system'">System settings</button><template v-if="tab==='Architecture'"><button @click="addComponent">Add component</button><button @click="addConnection">Connect components</button></template><button v-if="tab==='Claims'" @click="addClaim">Add claim</button><button v-if="tab==='Deployment'" @click="addPlan">Add deployment plan</button><button @click="validate" :disabled="!!busy">Validate</button><button @click="resolveReferences" :disabled="!!busy">Resolve references</button><button @click="run" :disabled="!!busy">Run reception conformance</button><button @click="loadHistory" :disabled="!!busy">Evidence history</button><span role="status">{{busy}}</span></div>
 </StudioRibbon>
 <p v-if="error" class="error-box" role="alert">{{error}}</p>
 <div v-if="validation && !validation.valid" class="error-box"><strong>Definitions need attention</strong><button v-for="issue in validation.issues" :key="issue.path+issue.message" class="issue" @click="locate(issue.path)">{{issue.path}}: {{issue.message}}</button></div>
 <nav class="perspectives" aria-label="System perspective"><button v-for="name in ['Architecture','Claims','Deployment','Evidence']" :key="name" :aria-current="tab===name?'page':undefined" @click="tab=name;panel=''">{{name}}</button></nav>
 <div v-if="resolution" class="resolution-summary" :class="resolution.valid?'satisfied':'inconclusive'"><strong>{{resolution.valid?'Direct references resolved':'References need attention'}}</strong><p>{{resolution.references.length}} checked references. This does not establish port compatibility or general execution support.</p><details><summary>Resolved identities and digests</summary><p v-for="ref in resolution.references" :key="ref.path">{{ref.path}} · {{ref.kind}} · {{ref.id}}@{{ref.version}}<br/><code>{{ref.digest}}</code> · {{ref.source}}</p></details></div>
 <div class="system-canvas">
  <template v-if="tab==='Architecture'">
   <div class="canvas-heading"><div><small>SYSTEM DESIGN · {{draft.revision}}</small><h2>{{draft.name}}</h2></div><div class="commands"><button :aria-expanded="libraryOpen" @click="libraryOpen=!libraryOpen">{{libraryOpen?'Hide library':'Show library'}}</button><button @click="addComponent">+ Component</button></div></div>
   <div class="architecture-layout" :class="{'library-hidden':!libraryOpen}"><SystemCatalogPanel v-if="libraryOpen" :entries="catalog" :selected-name="selectedComponent?.name" :busy="!!busy" @refresh="action('Refreshing catalog',refreshCatalog)" @add="addInstalled" @attach="attachArtifact"/><div class="architecture-design">
   <div v-if="!draft.components.length" class="empty"><h3>Start with an empty system</h3><p>Add a reusable component reference or load the reception example from File.</p><button @click="addComponent">Add first component</button></div>
   <div class="component-grid"><button v-for="(component,index) in draft.components" :key="component.id" class="component-card" :class="{selected:selected===component.id && panel==='component',invalid:invalid('components['+index+']')}" @click="selected=component.id;panel='component'"><span class="component-number">{{index+1}}</span><strong>{{component.name||'Unnamed component'}}</strong><span>{{component.definition.id||'Definition required'}}</span><small>Version {{component.definition.version||'required'}}</small><span class="component-meta">{{component.artifacts?.length||0}} artifact references · {{component.bindings?.length||0}} bindings</span></button></div>
   <div v-if="draft.connections.length" class="connections"><h3>Connections</h3><button v-for="connection in draft.connections" :key="connection.id" @click="panel='connections'">{{draft.components.find(c=>c.id===connection.source)?.name||connection.source}} <span>→ {{connection.kind}} →</span> {{draft.components.find(c=>c.id===connection.target)?.name||connection.target}}</button></div>
   </div></div>
  </template>
  <div v-if="tab==='Claims'" class="canvas-content"><div class="canvas-heading"><h2>Executable contract</h2><button @click="addClaim">+ Claim</button></div><div class="fields"><label>Contract ID *<input v-model="draft.contract.id" /></label><label>Revision *<input v-model="draft.contract.revision" /></label></div><p class="muted">The first evaluator supports four reception intake claims. Each check uses a complete, bounded execution trace.</p><p v-if="!draft.contract.claims.length" class="empty">No claims yet. Add an executable claim to define expected behavior.</p>
   <fieldset v-for="(claim,index) in draft.contract.claims" :key="index" :class="{invalid:invalid('contract.claims['+index+']')}"><legend>Claim {{index+1}}</legend><div class="fields"><label>Claim ID *<input v-model="claim.id" /></label><label>Evaluator *<select v-model="claim.kind"><option v-for="kind in claimKinds" :key="kind.id" :value="kind.id">{{kind.label}}</option></select></label></div><label>Description<input v-model="claim.description" /></label><button class="remove" @click="draft.contract.claims.splice(index,1)">Remove claim</button></fieldset>
   <h3>Declared assumptions</h3><div v-for="(assumption,index) in draft.contract.assumptions" :key="index" class="fields"><label>ID *<input v-model="assumption.id" /></label><label>Precondition *<input v-model="assumption.description" /></label><button @click="draft.contract.assumptions.splice(index,1)">Remove</button></div><button @click="draft.contract.assumptions.push({id:'assumption-'+(draft.contract.assumptions.length+1),description:''})">+ Assumption</button>
  </div>
  <div v-if="tab==='Deployment'" class="canvas-content"><div class="canvas-heading"><h2>Deployment plans</h2><button @click="addPlan">+ Plan</button></div><p class="muted">Declare resources and component placements separately from reusable definitions.</p><p v-if="!draft.deploymentPlans.length" class="empty">No deployment plans. Add one when you are ready to bind resources.</p><fieldset v-for="(plan,index) in draft.deploymentPlans" :key="index" :class="{invalid:invalid('deploymentPlans['+index+']')}"><legend>{{plan.name}}</legend><div class="fields"><label>Plan ID *<input v-model="plan.id" /></label><label>Name *<input v-model="plan.name" /></label></div><h3>Resources</h3><div v-for="(resource,r) in plan.resources" :key="r" class="fields"><label>Resource ID *<input v-model="resource.id" /></label><label>Kind *<select v-model="resource.kind"><option v-for="kind in ['compute','postgresql','redis','broker','network']" :key="kind">{{kind}}</option></select></label><button @click="plan.resources.splice(r,1)">Remove</button></div><button @click="plan.resources.push({id:'resource-'+(plan.resources.length+1),kind:'compute'})">+ Resource</button><h3>Placements</h3><div v-for="(placement,p) in plan.placements" :key="p" class="fields"><label>Component *<select v-model="placement.componentId"><option value="">Select component</option><option v-for="c in draft.components" :key="c.id" :value="c.id">{{c.name}}</option></select></label><label>Resource *<select v-model="placement.resourceId"><option value="">Select resource</option><option v-for="r in plan.resources.filter(r=>r.kind==='compute')" :key="r.id" :value="r.id">{{r.id}}</option></select></label><button @click="plan.placements.splice(p,1)">Remove</button></div><button @click="plan.placements.push({componentId:'',resourceId:''})">+ Placement</button><button class="remove" @click="draft.deploymentPlans.splice(index,1)">Remove plan</button></fieldset></div>
  <div v-if="tab==='Evidence'" class="canvas-content"><div class="canvas-heading"><h2>Conformance evidence</h2><button @click="run" :disabled="!!busy">Run experiment</button></div><p class="muted">Runs the fixed reception intake model and real PostgreSQL-backed Go implementation. Faulty deduplication and missing telemetry are intentional negative controls.</p><div v-if="history.length" class="history"><button v-for="item in history" :key="item.id" @click="evidence=item">{{new Date(item.createdAt).toLocaleString()}} · {{item.report.passed?'Expectations met':'Review required'}}</button></div><p v-if="!evidence" class="empty">Run the example to collect evidence. A database-backed run must be available; simulation results are never presented as real implementation evidence.</p><template v-if="evidence"><p v-if="staleEvidence" class="warning">This evidence belongs to a different design snapshot. Run again to evaluate the current design.</p><div class="evidence-summary" :class="evidence.report.passed?'satisfied':'violated'"><strong>{{evidence.report.passed?'Scenario expectations met':'Scenario expectations not met'}}</strong><span>Design {{evidence.report.designRevision}} · Contract {{evidence.report.contractRevision}} · {{evidence.id}}</span></div><details v-if="evidence.resolution" class="resolution-summary"><summary>Resolved references captured for this run ({{evidence.resolution.references.length}})</summary><p v-for="ref in evidence.resolution.references" :key="ref.path">{{ref.path}} · {{ref.id}}@{{ref.version}} · {{ref.source}}<br/><code>{{ref.digest}}</code></p><p>Definition digests identify catalog content or adapter declarations, not executable build provenance.</p></details><p v-else class="muted">This older run predates reference-resolution evidence.</p><p v-for="limit in evidence.report.limitations" :key="limit" class="muted">{{limit}}</p><details v-for="scenario in evidence.report.scenarios" :key="scenario.id" class="scenario"><summary>{{scenario.passed?'✓':'!'}} {{scenario.name}} <span>Expected implementation: {{scenario.expectedStatus}}</span></summary><div class="trace-grid"><section v-for="target in (['model','implementation'] as const)" :key="target"><h3>{{target==='model'?'Model':'Go implementation'}}</h3><div v-for="verdict in scenario[target].verdicts" :key="verdict.claimId" class="verdict" :class="verdict.status"><strong>{{verdict.claimId}} · {{verdict.status}}</strong><p>{{verdict.message}}</p><small>Evidence: {{verdict.evidenceSequences?.join(', ')||'none'}}</small></div><details><summary>Execution trace ({{scenario[target].events.length}} events)</summary><ol class="trace"><li v-for="event in scenario[target].events" :key="event.sequence"><strong>{{event.sequence}} · {{event.kind}}</strong><span>{{event.requestId}} {{event.encounterId}}</span><small>{{event.detail}}</small></li></ol></details></section></div></details></template></div>
  <CanvasInspector v-if="panel==='system'" title="System settings" @close="panel=''"><label>System ID *<input v-model="draft.id" /></label><label>Name *<input v-model="draft.name" /></label><label>Revision *<input v-model="draft.revision" /></label><p class="muted">Save writes this system ID. Use New empty system to create a separate design.</p></CanvasInspector>
  <CanvasInspector v-if="panel==='component' && selectedComponent" :title="selectedComponent.name||'Component settings'" @close="panel=''"><label>Name *<input v-model="selectedComponent.name" /></label><label>Instance ID<input :value="selectedComponent.id" readonly /></label><label :class="{invalid:invalid('components['+selectedIndex+'].definition')}">Definition ID *<input v-model="selectedComponent.definition.id" placeholder="health.reception.intake" /></label><label>Exact version *<input v-model="selectedComponent.definition.version" /></label><label>Definition kind<select v-model="selectedComponent.definition.kind"><option value="component">Behavior/timing package</option><option value="definition">Unified component definition</option></select></label><p v-if="selectedComponent.definition.kind==='definition'" class="muted">Owned aspects come from this installed component definition. Resolve references to inspect its pinned dependencies.</p><label>Use an installed definition<select @change="chooseDefinition"><option value="">Choose exact definition…</option><template v-for="(entry,index) in catalog" :key="entry.kind+entry.id+entry.version"><option v-if="entry.kind==='component'||entry.kind==='definition'" :value="index" :disabled="!entry.ready">{{entry.name}} · {{entry.version}} · {{entry.source}}</option></template></select></label><h3>Artifact references</h3><fieldset v-for="(artifact,index) in selectedComponent.artifacts" :key="index" :class="{invalid:invalid('components['+selectedIndex+'].artifacts['+index+']')}"><label>View *<select v-model="artifact.kind"><option v-for="kind in ['component','data','state','workflow','messages']" :key="kind">{{kind}}</option></select></label><label>Artifact ID *<input v-model="artifact.id" /></label><label>Version *<input v-model="artifact.version" /></label><button @click="selectedComponent.artifacts.splice(index,1)">Remove reference</button></fieldset><button @click="selectedComponent.artifacts.push({kind:'component',id:'',version:'1.0.0'})">+ Artifact reference</button><h3>Resource bindings</h3><fieldset v-for="(binding,index) in selectedComponent.bindings" :key="index"><label>Requirement *<input v-model="binding.requirement" /></label><label>Resource ID *<input v-model="binding.resourceId" list="system-resource-ids" /></label><button @click="selectedComponent.bindings.splice(index,1)">Remove binding</button></fieldset><datalist id="system-resource-ids"><option v-for="r in draft.deploymentPlans.flatMap(p=>p.resources)" :key="r.id" :value="r.id" /></datalist><button @click="selectedComponent.bindings.push({requirement:'',resourceId:''})">+ Binding</button><button class="remove" @click="removeComponent">Remove component and its connections</button></CanvasInspector>
  <CanvasInspector v-if="panel==='connections'" title="Component connections" @close="panel=''"><fieldset v-for="(connection,index) in draft.connections" :key="index" :class="{invalid:invalid('connections['+index+']')}"><legend>{{connection.id}}</legend><label>Source *<select v-model="connection.source"><option value="">Select component</option><option v-for="c in draft.components" :key="c.id" :value="c.id">{{c.name}}</option></select></label><label>Target *<select v-model="connection.target"><option value="">Select component</option><option v-for="c in draft.components" :key="c.id" :value="c.id">{{c.name}}</option></select></label><label>Connection kind *<select v-model="connection.kind"><option>request</option><option>event</option><option>data</option></select></label><button @click="draft.connections.splice(index,1)">Remove connection</button></fieldset><button @click="addConnection">+ Connection</button></CanvasInspector>
 </div>
</section>
</template>
<style scoped>
.architecture-layout{display:grid;grid-template-columns:240px minmax(0,1fr);gap:18px;align-items:start}.architecture-layout.library-hidden{grid-template-columns:minmax(0,1fr)}.architecture-design{min-width:0}.resolution-summary{padding:12px;border-radius:8px;margin:12px 0;font-size:12px;overflow-wrap:anywhere}.resolution-summary p{line-height:1.5}.resolution-summary details{max-height:220px;overflow:auto}.resolution-summary code{font-size:10px}@media(max-width:800px){.architecture-layout{grid-template-columns:1fr}.architecture-layout :deep(.system-library){max-height:240px}}

.system-workbench{min-width:0;padding:16px; color:#29495a}.commands,.perspectives{display:flex;gap:8px;align-items:center;flex-wrap:wrap}.system-workbench button{border:1px solid #c8dbe3;border-radius:6px;background:#fff;padding:8px 12px;color:#285c52;cursor:pointer;font:inherit;font-size:12px}.system-workbench button:hover{background:#eaf6f1}.system-workbench button:disabled{opacity:.5;cursor:wait}.perspectives{margin-bottom:10px}.perspectives button[aria-current]{background:#246e5d;color:#fff;border-color:#246e5d}.system-canvas{position:relative;min-height:580px;min-width:0;background:radial-gradient(#cfdde4 1px,transparent 1px) 0 0/20px 20px,#f7fafb;border:1px solid #d5e3e9;border-radius:12px;padding:20px;overflow:hidden}.canvas-heading{display:flex;justify-content:space-between;gap:12px;align-items:center;margin-bottom:24px;flex-wrap:wrap}.canvas-heading h2{font-size:20px;margin:4px 0}.canvas-heading small{color:#6b838d;letter-spacing:1px;font-size:10px}.component-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(240px,100%),1fr));gap:22px}.system-workbench .component-card{display:flex;flex-direction:column;align-items:flex-start;text-align:left;gap:9px;padding:20px;min-width:0;max-width:360px;border:1px solid #8eafa5;border-top:4px solid #338874;box-shadow:0 4px 14px #244a6310;overflow-wrap:anywhere}.component-card strong{font-size:16px}.component-number{border-radius:50%;padding:4px 8px;background:#e8f4ee;color:#39705b;font-size:11px}.component-meta{border-top:1px solid #dce8e4;padding-top:10px;color:#648078;font-size:11px;width:100%}.system-workbench .selected{outline:3px solid #55a990}.connections{margin-top:32px}.connections button{display:block;margin:8px 0;max-width:100%;overflow-wrap:anywhere;text-align:left}.connections span{color:#8d6cb0}.empty{text-align:center;padding:50px 12px;color:#66808f}.empty h3{color:#355e70}.canvas-content{max-width:1100px;margin:auto;background:#fff;padding:20px;border-radius:8px;min-width:0}.fields{display: